# openjiuwen 代码节点：侧线收率（sideline-yield）
# 节点类型 jiuwen.code，本地执行。平台调用 main(args) -> dict
#
# 迁移自 GET /api/v1/crude-tools/sideline-yield
#   query_engine.query_sideline_yields() + extract_crude_names() + _resolve_crude()
#
# 入参（在节点“输入参数”里配置，来自上游意图/开始节点）：
#   query        String 可选 —— 用户问句，工具自动从中提取原油名（推荐平台传这个）
#   crude_name   String 可选 —— 显式原油名，如 渤中25-1（优先级高于 query）
#   sample_date  String 可选 —— 采样日期 YYYYMMDD
#   sample_point String 可选 —— 采样点
# 出参：{"markdown": <展示文本>, "data": <侧线收率行列表>}


def main(args: dict) -> dict:
    import os
    import re
    import psycopg2
    from psycopg2.extras import RealDictCursor

    dsn = os.getenv(
        "DATABASE_URL",
        "postgresql://crude_qa:crude_qa2026@localhost:5432/crude_qa",
    )

    query = (args.get("query") or "").strip()
    crude_name = (args.get("crude_name") or "").strip()
    sample_date = (args.get("sample_date") or "").strip() or None
    sample_point = (args.get("sample_point") or "").strip() or None

    def _fmt(v):
        if v is None:
            return "-"
        if isinstance(v, float):
            return f"{v:.2f}".rstrip("0").rstrip(".")
        return str(v)

    conn = psycopg2.connect(dsn, connect_timeout=5)
    try:
        cur = conn.cursor(cursor_factory=RealDictCursor)

        # ── 原油名解析：显式优先，否则从 query 提取（精确 → 别名 → 正则兜底）──
        if not crude_name and query:
            cur.execute("SELECT DISTINCT crude_name FROM crude_oil ORDER BY crude_name")
            known = [r["crude_name"] for r in cur.fetchall()]
            # 1) 精确子串
            for cn in known:
                if cn in query:
                    crude_name = cn
                    break
            # 2) 别名（数字-数字 结构的常见口语变体）
            if not crude_name:
                for cn in known:
                    m = re.match(r"^(.+?)((\d+)-(\d+))$", cn)
                    if not m:
                        continue
                    prefix, _full, n1, n2 = m.group(1), m.group(2), m.group(3), m.group(4)
                    aliases = [
                        prefix + n1 + "年" + n2 + "月",
                        n1 + "年" + n2 + "月" + prefix,
                        n1 + "-" + n2 + prefix,
                        n1 + "." + n2 + prefix,
                        prefix + n1 + "." + n2,
                    ]
                    if any(a in query for a in aliases):
                        crude_name = cn
                        break
            # 3) 正则兜底：2-3 中文 + 数字 + 可选连字符
            if not crude_name:
                m = re.search(r"[一-鿿]{2,3}\d[\d\-]*", query)
                if m:
                    crude_name = m.group()

        if not crude_name:
            return {
                "markdown": "未能从问题中识别原油名称，请明确指定原油（如“渤中25-1 的侧线收率”）。",
                "data": [],
            }

        # ── 未指定批次时取最新批次（sample_date DESC）──
        if not sample_date:
            cur.execute(
                "SELECT DISTINCT sample_date, sample_point FROM crude_oil "
                "WHERE crude_name = %s ORDER BY sample_date DESC, sample_point",
                (crude_name,),
            )
            batches = cur.fetchall()
            if batches:
                sample_date = batches[0]["sample_date"]
                sample_point = batches[0]["sample_point"]

        # ── 查侧线收率 ──
        if sample_date and sample_point is not None:
            cur.execute(
                "SELECT * FROM sideline_yield WHERE crude_name = %s AND sample_date = %s "
                "AND sample_point = %s ORDER BY cut_temp_start",
                (crude_name, sample_date, sample_point),
            )
        elif sample_date:
            cur.execute(
                "SELECT * FROM sideline_yield WHERE crude_name = %s AND sample_date = %s "
                "ORDER BY cut_temp_start",
                (crude_name, sample_date),
            )
        else:
            cur.execute(
                "SELECT * FROM sideline_yield WHERE crude_name = %s ORDER BY cut_temp_start",
                (crude_name,),
            )
        rows = [dict(r) for r in cur.fetchall()]
        cur.close()
    finally:
        conn.close()

    if not rows:
        return {"markdown": f"未找到【{crude_name}】的侧线收率数据。", "data": []}

    label = rows[0].get("sample_date", "")
    sp = rows[0].get("sample_point", "")
    batch_label = f"{label}({sp})" if sp else label
    lines = [
        f"### {crude_name}（{batch_label}）各侧线收率\n",
        "| 侧线 | 切割温度 | 质量收率(%) |",
        "|:--|:--|--:|",
    ]
    for s in rows:
        cut = s.get("cut_label") or f"{_fmt(s.get('cut_temp_start'))}~{_fmt(s.get('cut_temp_end'))}℃"
        lines.append(f"| {s['sideline_name']} | {cut} | {_fmt(s.get('yield_mass_pct'))} |")

    # data 里的行可能含非 JSON 安全类型（如 Decimal），转成基本类型
    def _clean(v):
        if isinstance(v, float) or isinstance(v, int) or v is None or isinstance(v, str):
            return v
        return str(v)

    data = [{k: _clean(v) for k, v in r.items()} for r in rows]
    return {"markdown": "\n".join(lines), "data": data}

