        if crude_name:
            return crude_name
        if not query:
            return ""
        cur.execute("SELECT DISTINCT crude_name FROM crude_oil ORDER BY crude_name")
        known = [r["crude_name"] for r in cur.fetchall()]
        for cn in known:
            if cn in query:
                return cn
        for cn in known:
            m = re.match(r"^(.+?)((\d+)-(\d+))$", cn)
            if not m:
                continue
            prefix, _f, n1, n2 = m.group(1), m.group(2), m.group(3), m.group(4)
            aliases = [prefix + n1 + "年" + n2 + "月", n1 + "年" + n2 + "月" + prefix,
                       n1 + "-" + n2 + prefix, n1 + "." + n2 + prefix, prefix + n1 + "." + n2]
            if any(a in query for a in aliases):
                return cn
        m = re.search(r"[一-鿿]{2,3}\d[\d\-]*", query)
        return m.group() if m else ""

    def _classify(props):
        sulfur_val = acid_val = None
        for k, v in props.items():
            if "硫含量" in k:
                try:
                    sulfur_val = float(v)
                except Exception:
                    pass
            if k == "酸值":
                try:
                    acid_val = float(v)
                except Exception:
                    pass
        sc = ac = ""
        if sulfur_val is not None:
            sc = "低硫" if sulfur_val < 3000 else ("含硫" if sulfur_val < 10000 else "高硫")
        if acid_val is not None:
            ac = "高酸" if acid_val > 1.0 else ("含酸" if acid_val > 0.5 else "低酸")
        return sc, ac

    conn = psycopg2.connect(dsn, connect_timeout=5)
    try:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        crude_name = _resolve_crude(cur, crude_name, query)
        if not crude_name:
            return {"markdown": "未能从问题中识别原油名称，请明确指定原油（如“渤中25-1 的原油性质”）。",
                    "data": None, "classification": ""}

        # 批次取最新
        if not sample_date:
            cur.execute("SELECT DISTINCT sample_date, sample_point FROM crude_oil "
                        "WHERE crude_name = %s ORDER BY sample_date DESC, sample_point", (crude_name,))
            b = cur.fetchall()
            if b:
                sample_date, sample_point = b[0]["sample_date"], b[0]["sample_point"]

        if sample_date and sample_point is not None:
            cur.execute("SELECT * FROM crude_oil WHERE crude_name = %s AND sample_date = %s AND sample_point = %s",
                        (crude_name, sample_date, sample_point))
        elif sample_date:
            cur.execute("SELECT * FROM crude_oil WHERE crude_name = %s AND sample_date = %s LIMIT 1",
                        (crude_name, sample_date))
        else:
            cur.execute("SELECT * FROM crude_oil WHERE crude_name = %s LIMIT 1", (crude_name,))
        row = cur.fetchone()

        # 文字描述（section_num=1 原油一般性质）——PG 表精确取，替代 ChromaDB
        cur.execute("SELECT * FROM text_description WHERE crude_name = %s AND section_num = %s",
                    (crude_name, "1"))
        text_rows = [dict(r) for r in cur.fetchall()]
        cur.close()
    finally:
        conn.close()

    if not row:
        return {"markdown": f"未找到【{crude_name}】的原油性质数据。", "data": None, "classification": ""}

    row = dict(row)
    props = row.get("properties") or {}
    if isinstance(props, str):
        props = json.loads(props)
    sd = row.get("sample_date", "")
    sp = row.get("sample_point", "")
    batch_label = f"{sd}({sp})" if sp else sd

    sulfur_cat, acid_cat = _classify(props)
    classification = f"{sulfur_cat}{acid_cat}原油" if (sulfur_cat or acid_cat) else ""

    lines = [f"### {crude_name}（{batch_label}）原油一般性质\n"]
    if classification:
        lines.append(f"**分类结论**：{classification}\n")
    lines.append("| 指标 | 数值 |")
    lines.append("|:--|--:|")
    for k, v in props.items():
        lines.append(f"| {k} | {_fmt(v)} |")
    if text_rows:
        lines.append("\n**评价描述**：")
        for td in text_rows:
            c = (td.get("content") or "").strip()
            if c:
                lines.append(f"> {c}")

    data = {"crude_name": crude_name, "sample_date": sd, "sample_point": sp,
            "batch_label": batch_label, "properties": props}
    return {"markdown": "\n".join(lines), "data": data, "classification": classification}

# openjiuwen 代码节点：渣油性质（residue）
# 节点类型 jiuwen.code，本地执行。平台调用 main(args) -> dict
#
# 迁移自 GET /api/v1/crude-tools/residue
#   query_residue_properties() + get_residue_processing_suggestion()
#   + 文字描述走 PG text_description（section_num=8 渣油）
#
# 入参：query / crude_name / temp_range(如 >350℃ / >540℃) / sample_date / sample_point
# 出参：{"markdown", "data", "processing_suggestions"}


def main(args: dict) -> dict:
    import os
    import re
    import json
    import psycopg2
    from psycopg2.extras import RealDictCursor

    dsn = os.getenv(
        "DATABASE_URL",
        "postgresql://crude_qa:crude_qa2026@localhost:5432/crude_qa",
    )

    query = (args.get("query") or "").strip()
    crude_name = (args.get("crude_name") or "").strip()
    temp_range = (args.get("temp_range") or "").strip() or None
    sample_date = (args.get("sample_date") or "").strip() or None
    sample_point = (args.get("sample_point") or "").strip() or None

    def _fmt(v):
        if v is None:
            return "-"
        if isinstance(v, float):
            return f"{v:.2f}".rstrip("0").rstrip(".")
        return str(v)

    def _resolve_crude(cur, crude_name, query):
        if crude_name:
            return crude_name
        if not query:
            return ""
        cur.execute("SELECT DISTINCT crude_name FROM crude_oil ORDER BY crude_name")
        known = [r["crude_name"] for r in cur.fetchall()]
        for cn in known:
            if cn in query:
                return cn
        for cn in known:
            m = re.match(r"^(.+?)((\d+)-(\d+))$", cn)
            if not m:
                continue
            prefix, _f, n1, n2 = m.group(1), m.group(2), m.group(3), m.group(4)
            aliases = [prefix + n1 + "年" + n2 + "月", n1 + "年" + n2 + "月" + prefix,
                       n1 + "-" + n2 + prefix, n1 + "." + n2 + prefix, prefix + n1 + "." + n2]
            if any(a in query for a in aliases):
                return cn
        m = re.search(r"[一-鿿]{2,3}\d[\d\-]*", query)
        return m.group() if m else ""

    def _suggestion(tr):
        if tr == ">350℃":
            return "该原油>350℃常压渣油，可掺入减压馏分油中作催化裂化原料或作渣油加氢原料"
        if tr == ">540℃":
            return "该原油>540℃减压渣油，可掺入减压馏分油中做催化裂化原料或做渣油加氢原料"
        return ""

    conn = psycopg2.connect(dsn, connect_timeout=5)
    try:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        crude_name = _resolve_crude(cur, crude_name, query)
        if not crude_name:
            return {"markdown": "未能从问题中识别原油名称，请明确指定原油（如“渤中25-1 的渣油性质”）。",
                    "data": [], "processing_suggestions": []}

        if not sample_date:
            cur.execute("SELECT DISTINCT sample_date, sample_point FROM crude_oil "
                        "WHERE crude_name = %s ORDER BY sample_date DESC, sample_point", (crude_name,))
            b = cur.fetchall()
            if b:
                sample_date, sample_point = b[0]["sample_date"], b[0]["sample_point"]

        base = "crude_name = %s"
        params = [crude_name]
        if sample_date and sample_point is not None:
            base += " AND sample_date = %s AND sample_point = %s"
            params += [sample_date, sample_point]
        elif sample_date:
            base += " AND sample_date = %s"
            params += [sample_date]
        if temp_range:
            cur.execute(f"SELECT * FROM residue_properties WHERE {base} AND temperature_range = %s",
                        tuple(params + [temp_range]))
        else:
            cur.execute(f"SELECT * FROM residue_properties WHERE {base} ORDER BY temperature_range",
                        tuple(params))
        rows = [dict(r) for r in cur.fetchall()]

        cur.execute("SELECT * FROM text_description WHERE crude_name = %s AND section_num = %s",
                    (crude_name, "8"))
        text_rows = [dict(r) for r in cur.fetchall()]
        cur.close()
    finally:
        conn.close()

    if not rows:
        return {"markdown": f"未找到【{crude_name}】的渣油性质数据。", "data": [], "processing_suggestions": []}

    lines = [f"### {crude_name} 渣油性质\n"]
    suggestions = []

    # 优先 residue_list（规整结构）
    residue_list = None
    for item in rows:
        rl = item.get("residue_list")
        if isinstance(rl, str):
            rl = json.loads(rl)
        if rl:
            residue_list = rl
            break

    if residue_list:
        lines.append("| 指标 | 单位 | >350℃ | >540℃ |")
        lines.append("|:--|:--|--:|--:|")
        for r in residue_list:
            lines.append(f"| {r.get('name', '')} | {r.get('unit', '') or '-'} | "
                         f"{_fmt(r.get('val_350'))} | {_fmt(r.get('val_540'))} |")
            rec = (r.get("recommendation") or "").strip()
            if rec:
                suggestions.append({"name": r.get("name", ""), "recommendation": rec})
    else:
        for item in rows:
            tr = item.get("temperature_range", "")
            props = item.get("properties", {})
            if isinstance(props, str):
                props = json.loads(props)
            if isinstance(props, dict) and set(props.keys()) == {"properties"}:
                props = props["properties"]
            lines.append(f"\n**{tr}**\n")
            lines.append("| 指标 | 数值 |")
            lines.append("|:--|--:|")
            for k, v in props.items():
                lines.append(f"| {k} | {_fmt(v)} |")
            sug = _suggestion(tr)
            if sug:
                suggestions.append({"temperature_range": tr, "suggestion": sug})
                lines.append(f"\n加工建议：{sug}")

    if text_rows:
        lines.append("\n**评价描述**：")
        for td in text_rows:
            c = (td.get("content") or "").strip()
            if c:
                lines.append(f"> {c}")

    def _clean(v):
        if v is None or isinstance(v, (int, float, str)):
            return v
        if isinstance(v, (dict, list)):
            return v
        return str(v)

    data = [{k: _clean(v) for k, v in r.items()} for r in rows]
    return {"markdown": "\n".join(lines), "data": data, "processing_suggestions": suggestions}

