        md = f"未找到【{crude_name}】的关键馏分分类数据。"
        if combined:
            md += f"\n\n硫/酸综合分类：**{combined}**"
        return {"markdown": md, "data": None, "combined_classification": combined}

    frac_row = dict(frac_row)
    fractions = frac_row.get("fractions")
    if isinstance(fractions, str):
        fractions = json.loads(fractions)
    sd2 = frac_row.get("sample_date", "")
    sp2 = frac_row.get("sample_point", "")
    batch_label = f"{sd2}({sp2})" if sp2 else sd2

    lines = [f"### {crude_name}（{batch_label}）关键馏分分类\n"]
    if frac_row.get("classification"):
        lines.append(f"**分类结论**：{frac_row['classification']}\n")
    if combined:
        lines.append(f"**硫/酸分类**：{combined}（硫:{sulfur_cat or '-'} / 酸:{acid_cat or '-'}）\n")
    if isinstance(fractions, list) and fractions:
        keys = list(fractions[0].keys())
        lines.append("| " + " | ".join(keys) + " |")
        lines.append("|" + "|".join(":--" for _ in keys) + "|")
        for fr in fractions:
            lines.append("| " + " | ".join(_fmt(fr.get(k)) for k in keys) + " |")

    data = {"crude_name": crude_name, "batch_label": batch_label,
            "fractions": fractions, "classification": frac_row.get("classification", "")}
    return {"markdown": "\n".join(lines), "data": data,
            "combined_classification": combined}

# openjiuwen 代码节点：多原油侧线收率对比（compare）
# 节点类型 jiuwen.code，本地执行。平台调用 main(args) -> dict
#
# 迁移自 POST /api/v1/crude-tools/compare
#   compare_crude_yields() + markdown 对比表 + matplotlib 分组柱状图(base64 内嵌)
#
# 入参：
#   query        String 可选 —— 用户问句，自动提取多个原油名（推荐）
#   crude_names  String 可选 —— 逗号/顿号分隔的原油名，如 "渤中25-1,锦州251"（优先）
#   sample_date  String 可选
#   sample_point String 可选
# 出参：{"markdown"(对比表格), "data"}
#
# 注：平台对话页(marked)无原生图表能力，也不认 echarts/mermaid，故只出 Markdown
#     对比表格。结构化 data 仍返回，供下游/自建前端按需自行画图。


def main(args: dict) -> dict:
    import os
    import re
    import psycopg2
    from psycopg2.extras import RealDictCursor

    dsn = os.getenv(
        "DATABASE_URL",
        "postgresql://crude_qa:crude_qa2026@localhost:5432/crude_qa",
    )
    SIDELINE_ORDER = ["石脑油", "常一线", "常二线", "常三线", "减一线",
                      "减二线", "减三线", "减四线", "渣油"]

    query = (args.get("query") or "").strip()
    crude_names_raw = (args.get("crude_names") or "").strip()
    sample_date = (args.get("sample_date") or "").strip() or None
    sample_point = (args.get("sample_point") or "").strip() or None

    def _fmt(v):
        if v is None:
            return "-"
        if isinstance(v, float):
            return f"{v:.2f}".rstrip("0").rstrip(".")
        return str(v)

    def _extract_names(cur, query):
        cur.execute("SELECT DISTINCT crude_name FROM crude_oil ORDER BY crude_name")
        known = [r["crude_name"] for r in cur.fetchall()]
        found = [cn for cn in known if cn in query]
        if found:
            return found
        # 别名匹配
        for cn in known:
            m = re.match(r"^(.+?)((\d+)-(\d+))$", cn)
            if not m:
                continue
            prefix, _f, n1, n2 = m.group(1), m.group(2), m.group(3), m.group(4)
            aliases = [prefix + n1 + "年" + n2 + "月", n1 + "年" + n2 + "月" + prefix,
                       n1 + "-" + n2 + prefix, n1 + "." + n2 + prefix, prefix + n1 + "." + n2]
            if any(a in query for a in aliases) and cn not in found:
                found.append(cn)
        if found:
            return found
        # 正则兜底（可能多个）
        return re.findall(r"[一-鿿]{2,3}\d[\d\-]*", query)

    def _latest_batch(cur, crude_name):
        cur.execute("SELECT DISTINCT sample_date, sample_point FROM crude_oil "
                    "WHERE crude_name = %s ORDER BY sample_date DESC, sample_point", (crude_name,))
        b = cur.fetchall()
        return (b[0]["sample_date"], b[0]["sample_point"]) if b else (None, None)

    def _query_yields(cur, crude_name, sd, sp):
        if sd and sp is not None:
            cur.execute("SELECT * FROM sideline_yield WHERE crude_name = %s AND sample_date = %s "
                        "AND sample_point = %s ORDER BY cut_temp_start", (crude_name, sd, sp))
        elif sd:
            cur.execute("SELECT * FROM sideline_yield WHERE crude_name = %s AND sample_date = %s "
                        "ORDER BY cut_temp_start", (crude_name, sd))
        else:
            n_sd, n_sp = _latest_batch(cur, crude_name)
            if n_sd:
                cur.execute("SELECT * FROM sideline_yield WHERE crude_name = %s AND sample_date = %s "
                            "AND sample_point = %s ORDER BY cut_temp_start", (crude_name, n_sd, n_sp))
            else:
                cur.execute("SELECT * FROM sideline_yield WHERE crude_name = %s ORDER BY cut_temp_start",
                            (crude_name,))
        return [dict(r) for r in cur.fetchall()]

    # ── 解析原油名列表 ──
    crude_names = []
    if crude_names_raw:
        crude_names = [c.strip() for c in re.split(r"[,，、\s]+", crude_names_raw) if c.strip()]

    conn = psycopg2.connect(dsn, connect_timeout=5)
    try:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        if len(crude_names) < 2 and query:
            crude_names = _extract_names(cur, query)
        if len(crude_names) < 2:
            return {"markdown": "收率对比至少需要两种原油，请明确指定（如“渤中25-1 和 锦州251 收率对比”）。",
                    "data": {}}

        result = {}
        for name in crude_names:
            yields = _query_yields(cur, name, sample_date, sample_point)
            if yields:
                result[name] = yields
        cur.close()
    finally:
        conn.close()

    if not result:
        return {"markdown": "未找到可对比的收率数据。", "data": {}}

    cols = list(result.keys())
    lines = ["### 侧线收率对比\n", "| 侧线 | " + " | ".join(cols) + " |",
             "|:--|" + "".join("--:|" for _ in cols)]
    for sn in SIDELINE_ORDER:
        row = f"| {sn} |"
        for cn in cols:
            found = next((y for y in result.get(cn, []) if y.get("sideline_name") == sn), None)
            row += f" {_fmt(found.get('yield_mass_pct')) if found else '-'} |"
        lines.append(row)

    def _clean(v):
        if v is None or isinstance(v, (int, float, str, dict, list)):
            return v
        return str(v)

    data = {k: [{kk: _clean(vv) for kk, vv in row.items()} for row in rows]
            for k, rows in result.items()}
    return {"markdown": "\n".join(lines), "data": data}
